import{_ as o,l as s,o as a,c as n,v as r,p as l,x as i,d,i as p,S as c}from"./chunks/framework.InCnrqk-.js";const k=JSON.parse('{"title":"Trie","description":"","frontmatter":{"title":"Trie","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/trie.md","filePath":"cs/trie.md","lastUpdated":1789023840000}'),h={name:"cs/trie.md"};function T(_,e,m,u,f,S){const t=s("Mermaid");return a(),n("div",null,[e[1]||(e[1]=r('<h1 id="trie" tabindex="-1">Trie <a class="header-anchor" href="#trie" aria-label="Permalink to &quot;Trie&quot;">​</a></h1><div class="epigraph"><p>键是串时，沿字符往下走，比较次数跟键长走，不跟表里有多少个键走；公共前缀只存一次。</p><footer>—— 据 Fredkin, Trie Memory, CACM 1960；Cormen, Leiserson, Rivest and Stein 整理</footer></div><p><a href="/cs/skip-list">上一课</a>和<a href="/cs/hash-function">散列函数</a>把整键当作一次比较或一次 \\(h(k)\\)。<a href="/cs/skip-list">字符与 Unicode</a>已经把串写成符号序列。本课不重讲跳表层高。缺口是：字典树按符号位（通常是字符）分支，查找代价 \\(\\Theta(L)\\)，\\(L\\) 为键长，与 \\(n\\) 弱相关，且前缀共享省空间、支持前缀查询。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>许多键共享前缀（路径、单词）时，BST 仍从根比较整键，散列仍把整键搅成槽。缺口不是更好的 \\(h\\)，而是<strong>边标字符、节点表示「走到这个前缀」</strong>。结束标记表示该前缀是完整键。</p><p>扇出等于字母表大小 \\(|\\Sigma|\\)。\\(\\Sigma\\) 大则数组孩子浪费，\\(\\Sigma\\) 小则数组正好吃局部性。实现可把孩子做成哈希表或有序向量——那是表示选择，ADT 是沿符号下降。</p><p><span class="marginnote">Trie 不是 tree 的拼写错误。Fredkin 从 retrieval 造词。Patricia/radix 压缩单孩子路径，本课点名不展开。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>根对应空前缀。插入键 \\(c_1\\ldots c_L\\)：逐字符走或建边，末节点打结束位并可挂卫星。查找同样下降，缺边或末节点无结束位则失败。删除要考虑是否剪无兄弟的尾——可选。</p>',9)),(a(),l(c,null,{default:i(()=>[p(t,{id:"mermaid-25",class:"mermaid",graph:"flowchart%20TD%0A%20%20R%5B%22%E6%A0%B9%20%CE%B5%22%5D%20--%3E%20T%5B%22t%22%5D%0A%20%20T%20--%3E%20TE%5B%22e%22%5D%0A%20%20T%20--%3E%20TO%5B%22o%22%5D%0A%20%20TE%20--%3E%20TEA%5B%22a%20%E7%BB%93%E6%9D%9F%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[d(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<p>与 BST 比较：BST 一次比较整键，\\(h\\log n\\)；Trie 一次比较一个符号，\\(L\\) 步。短键、大 \\(n\\) 时 Trie 可更快；长随机键则 \\(L\\) 本身很大。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>前缀查询：降到前缀节点，遍历子树列出全部结束标记。有序树要从 lower_bound 扫到前缀外；散列做不到。这是 Trie 作为字典的独特合同。</p><p>空间：最坏 \\(\\Theta(\\sum L_i)\\) 节点。压缩路径后接近相异前缀的总量。cache：沿指针下降，类似树的追逐；孩子数组在 \\(|\\Sigma|\\) 小时更连续。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不把后缀树、AC 自动机写进来。也不进入大模型词表——那是另一栏的离散符号。Unicode 字母表很大，直接 256 路只适合字节；按码点要再编码。</p><p>后课默认：串键、前缀操作可用 Trie。不相交集合的合并查找是另一合同：并查集，键是元素编号而非串。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Trie 按字符下降，时间跟键长，\\(n\\) 只影响扇出实现。</li><li>公共前缀共享；前缀枚举自然。</li><li>并查集管「同属一类」，不保管键，下一课。</li><li>出处：Fredkin, <em>CACM</em>, 1960；Cormen et al. 对数字查找树的讨论。</li></ul>',9))])}const B=o(h,[["render",T]]);export{k as __pageData,B as default};
